package fr.thibautperrin.tetrano.data.assets

import android.content.Context
import dagger.hilt.android.qualifiers.ApplicationContext
import fr.thibautperrin.tetrano.R
import fr.thibautperrin.tetrano.engine.puzzle.Puzzle
import javax.inject.Inject
import javax.inject.Singleton

/** The Puzzles mode's built-in puzzles (generated by `selfplay puzzles`, see tools/nn/README.md). */
interface PuzzleCatalog {
    /** Loaded on first use (off the main thread: callers are on the default dispatcher). */
    val puzzles: List<Puzzle>
}

/** Reads `res/raw/puzzles.bin` once. */
@Singleton
class PuzzleDataSource @Inject constructor(@ApplicationContext private val context: Context) : PuzzleCatalog {
    override val puzzles: List<Puzzle> by lazy {
        context.resources.openRawResource(R.raw.puzzles).use { Puzzle.readAll(it) }
    }
}
